
const PARAS={"IRRS 55": {"s": "IRRS 2018, para 55", "t": "Where large numbers of people are fleeing armed violence and conflict or other mass violations of human rights, it may be neither practical nor necessary to examine individual claims for refugee status. In such circumstances, <mark>States and UNHCR may decide to recognize refugee status for the entire group</mark>. … Every member of the group is considered a refugee prima facie …"}, "IRRS 59": {"s": "IRRS 2018, para 59", "t": "… In order to uphold family unity in the refugee context, <mark>States may grant nationality to the children born to refugees in the country of asylum. In such circumstances, the children are not refugees</mark> because they enjoy the protection of their State, or parents’ country of asylum … Despite not being refugees, it is important for statistical and analytical purposes to capture the number of children of refugees notwithstanding their status."}, "IRRS 60": {"s": "IRRS 2018, para 60", "t": "In the absence of a provision in the nationality legislation that would allow the child of a refugee to acquire the nationality of the country of asylum at birth, the principle of family unity may be upheld by <mark>granting refugee status to the spouse and dependants of a refugee</mark> so that they are able to enjoy their right to family unity. When spouses and dependants acquire refugee status on this basis, they are said to enjoy <mark>“derivative refugee status”</mark>, which entitles them to the full benefits of the 1951 Convention."}, "IRRS 67": {"s": "IRRS 2018, para 67", "t": "The last two cessation clauses, Article 1C(5) and (6), are based on the consideration that <mark>international protection is no longer justified on account of changes in the country where persecution was feared</mark>, because the reasons for a person becoming a refugee have ceased to exist. They are known as the “ceased circumstances clauses”."}, "IRRS 78": {"s": "IRRS 2018, para 78", "t": "Similarly, <mark>not all refugee and refugee related persons in scope of these recommendations are foreign citizens</mark>, as some may take the citizenship of their host country … although <mark>Palestine Refugees with protection under the UNRWA mandate</mark> (see Chapter 2, Section (3)) <mark>are treated as refugees regardless of nationality</mark>. … Children born of refugees and asylum seekers in the host country may or may not be entitled to citizenship."}, "IRRS 80": {"s": "IRRS 2018, para 80", "t": "… the fact that they may be classified as international migrants for statistical purposes has no bearing on their legal status. Further, it should be noted that some refugees and other persons in need of international protection may not satisfy the international migrant definition set out in this chapter, <mark>often because they are refugees sur place or because they were born in exile to refugee parents. Therefore, not all refugees meet the statistical definition of international migrants.</mark>"}, "IRRS 84": {"s": "IRRS 2018, para 84", "t": "… If a foreign person enters the host country for international protection reasons, <mark>with the intention of staying for at least one year, this person should be considered as an immigrant</mark>. For a refugee who returns to his or her country of habitual residence after having sought protection abroad and if this person intends to stay in the home country for at least one year, then <mark>this person should be considered an immigrant into his or her home country</mark>. These people are also defined as returned migrants."}, "IRRS 85": {"s": "IRRS 2018, para 85", "t": "However, there may be difficulties in using the concept of usual residence for potential and actual asylum seekers, as many people fleeing their countries of origin are in an impermanent position, and their destination is often undefined. <mark>If they have the intention of staying in the country for a year then they should be included in the migrant count.</mark> <mark>Asylum seekers in transit to another country are excluded</mark> from the scope of these recommendations."}, "IRRS 90": {"s": "IRRS 2018, para 90", "t": "… While most of the individuals in this category will be foreign citizens who have immigrated to seek protection, <mark>others may have been born in the host country to refugees or asylum seekers</mark>. … this category includes children of refugees or asylum-seekers who may have been born in the country of asylum, but who have not themselves acquired the citizenship of their host country … This category also includes <mark>Palestine Refugees recognized under UNRWA’s mandate who may have been born in the host country and who may have acquired citizenship of the host country</mark>."}, "IRRS 92.1": {"s": "IRRS 2018, para 92.1", "t": "Prospective asylum seekers: Persons with the intention of filing an application for asylum, but who have not yet done so for reasons which include <mark>being unable to file an application because of practical or administrative obstacles</mark> including capacity constraints in the receiving country authorities. Asylum seekers in transit to another country are excluded …"}, "IRRS 92.2": {"s": "IRRS 2018, para 92.2", "t": "Asylum seekers: Persons who have filed an application for asylum in a country other than their own and whose claims have not yet been determined. … <mark>The date on which the application for asylum is filed marks their entry into the status of asylum seeker.</mark>"}, "IRRS 92.3": {"s": "IRRS 2018, para 92.3", "t": "Persons with determined protection status: … three sub-categories are available: i) Refugees … ii) <mark>Admitted for complementary and subsidiary forms of protection</mark> … iii) <mark>Admitted for temporary protection</mark>: Persons who are granted temporary legal status in the host country because their lives would be in danger if they were to return to their home countries."}, "IRRS 92.4": {"s": "IRRS 2018, para 92.4", "t": "Others in refugee-like situations: … This group may include people who enter the country: <mark>(i) on tourist, student or work visas; (ii) pursuant to humanitarian stay programs; or (iii) in accordance with treaties guaranteeing free movements within a defined area</mark>, provided that the underlying reason for their presence in the host country is tied to their need for international protection."}, "IRRS 93": {"s": "IRRS 2018, para 93", "t": "… persons who previously held refugee status but have been naturalised and acquired citizen status; <mark>those born in the host country of refugee parents or grandparents with the citizenship of the family’s host country</mark>; … <mark>There may also be persons who would be eligible for citizenship of the host country, but who have decided not to avail themselves of it.</mark>"}, "IRRS 94.1": {"s": "IRRS 2018, para 94.1", "t": "Naturalised former refugees: These persons were once refugees in the host country, but who no longer have refugee status because <mark>they are now naturalised citizens of the host country</mark> …"}, "IRRS 94.2": {"s": "IRRS 2018, para 94.2", "t": "Children and descendants of refugees: These persons are born of one or more refugee parents, and who are not themselves in need of international protection, <mark>usually because they have citizenship of the host country</mark>. Children born of refugee parents who have not acquired the citizenship of the host country should be included in category (a) …"}, "IRRS 94.3": {"s": "IRRS 2018, para 94.3", "t": "Family member reunification: Those people who have joined refugee families or former refugee families from abroad through a process of family reunification are included here. <mark>The category does not include locally born or citizen family members</mark> who have joined households by marriage or by household formation."}, "IRRS 94.4": {"s": "IRRS 2018, para 94.4", "t": "Others with a refugee background: These include any others who have a refugee background who are not currently refugees. <mark>It may include those whose protection has ceased but who remain in the country of concern.</mark>"}, "IRRS 95": {"s": "IRRS 2018, para 95", "t": "These are persons who have returned to their home country after seeking international assistance abroad. The home country is defined legally as <mark>the country of former habitual residence</mark>, and is usually their country of citizenship, but <mark>it may be that of their parents or grandparents who fled many years ago</mark> … For stateless persons, the previous country of residence could be considered as the home country."}, "IRRS 96": {"s": "IRRS 2018, para 96", "t": "… this category includes those who have sought asylum abroad, have failed to gain refugee status, and have returned to their home country. … <mark>They may be difficult to identify in their home country, as most will hold citizenship of the country to which they are returning and may be invisible to immigration records.</mark>"}, "IRRS 97": {"s": "IRRS 2018, para 97", "t": "Persons returned from abroad after having sought international protection include: 1. Repatriating refugees … 2. Repatriating asylum seekers … 3. Returning after having received international protection other than refugee status abroad … 4. <mark>Others returning from seeking international protection abroad</mark> … The category might include those who intended to seek international protection abroad but were admitted by another country for other purposes, such as tourism, study or labour."}, "IRRS 97.1": {"s": "IRRS 2018, para 97.1", "t": "Repatriating refugees: <mark>Persons, likely to be citizens, who have returned to their home country after having enjoyed asylum abroad</mark>. Both refugees returning under internationally assisted repatriation programmes and those returning spontaneously should be included in this category."}, "IRRS 97.2": {"s": "IRRS 2018, para 97.2", "t": "Repatriating asylum seekers: Persons returning after having attempted to seek asylum abroad. To the extent possible, this category should include <mark>persons who return after their asylum applications have been decided negatively</mark> as well as persons who may not have been able to apply for asylum …"}, "IRRS 101": {"s": "IRRS 2018, para 101", "t": "In the context of refugee statistics, the situation is more complex than crossing a national border, as <mark>persons may enter the stock at several points, by birth, by migration or by being granted citizenship of the host country or by changes in their international protection status</mark>. They may also exit by death, migration or by changing their legal status or citizenship."}, "IRRS 105b": {"s": "IRRS 2018, para 105b", "t": "<mark>National inflow includes births of children of refugee or asylum-seeking parents in the host country.</mark> National outflow includes deaths. <mark>Within the refugee and refugee related populations individuals may change their status</mark> by having asylum applications granted, ceased, cancelled or revoked. Others may receive citizen status by a process of naturalisation."}, "IRRS 109": {"s": "IRRS 2018, para 109", "t": "… citizens who have returned to their country of previous habitual residence after having sought international protection abroad (see Figure 3.2). <mark>Since persons of this group are usually citizens of the country to which they are returning they are counted in the concept of stocks as well as flows.</mark> The stock figure of former refugees in the country of return has limited informational value as well as practical limitations."}, "IRRS Box 3.1": {"s": "IRRS 2018, Box 3.1", "t": "Description of inflows of persons entering a country for international protection reasons … <mark>Reunified refugee family members: Number of foreign citizens entering a country within the reference year who have been authorised to join existing refugee family members.</mark>"}, "IMTM 17": {"s": "IMTM 2025, para 17", "t": "… the resident population is defined for statistical purposes as the population with place of residence in the country, provided they meet the minimum duration of residence requirement (actual or intended) in the country, <mark>regardless of their legal status or the purpose of this residence</mark> (e.g. education, family unification, work or self-employment, international protection and other humanitarian reasons). In other words, <mark>the resident population includes … asylum seekers and persons who applied for or were granted refugee status</mark> or similar types of international protections."}, "IMTM 23": {"s": "IMTM 2025, para 23", "t": "… The resident population changes between time t and t+n by the addition of new residents and births and the subtraction of previous residents … and deaths. … <mark>Note, residents who are temporarily staying in other countries are not removed from the (origin) resident population.</mark>"}, "IMTM 25": {"s": "IMTM 2025, para 25", "t": "For the purposes of measuring international migration, <mark>the immigrant population (stock) includes all persons who reside in the country who are either born in another country or who do not hold national citizenship</mark> (including stateless persons) at a given point in time. Persons entering the country and becoming part of the resident population in a given year (flow) are considered immigrants … <mark>Persons who are born in the country and have national citizenship are not considered part of the immigrant population</mark>, although they can be considered (recent) immigrants or part of the immigration flow if they returned and changed their country of residence."}, "IMTM 27": {"s": "IMTM 2025, para 27", "t": "<mark>Returned migrants (stock) refer to persons who previously resided in the country of measurement</mark> (i.e. met the duration of stay criteria for residence) <mark>who emigrated and subsequently came back to live in the country</mark> and stayed or intended to stay for the minimum duration required for residence."}, "IMTM 30": {"s": "IMTM 2025, para 30", "t": "<mark>Temporary population include forcibly displaced persons which result in stays of less than the minimum duration of stay, such as asylum seekers and other persons in transit</mark> and those who move for environment or climate-related reasons. It should be noted that displacement situations that are not quickly resolved may become protracted."}, "IMTM 33": {"s": "IMTM 2025, para 33", "t": "… the duration of stay for asylum seekers may not be known until a decision has been made regarding their application for refugee status. In this case, the person or family may stay for a few days or even longer than a year to receive a decision. <mark>If the legal process takes longer than the minimum duration requirement for residence, as it often does, then that person or family should be considered part of the resident population.</mark>"}, "IMTM 34": {"s": "IMTM 2025, para 34", "t": "… <mark>Refugees and persons in refugee-like situations born outside their country of asylum</mark> will, therefore, in most cases eventually meet the minimum duration requirement for a change in their country of residence. They should generally be counted as international migrants for statistical purposes and be added to the resident population of their country of asylum <mark>as foreign-born foreign citizens</mark>. … Statistical systems should <mark>maintain the capacity to separately identify and analyse refugee and asylum-seeker populations</mark> in alignment with the International Recommendations on Refugee Statistics (IRRS) …"}, "IMTM 37h": {"s": "IMTM 2025, para 37h", "t": "[Included in the resident population:] h. <mark>Children born in the 12 months before the reference time and whose families are residents in the country</mark>."}, "IMTM 37f": {"s": "IMTM 2025, para 37f", "t": "[Included in the resident population:] f. Asylum seekers and persons who have applied for, or been granted, refugee status or similar types of international protections, regardless of the type of living quarters in which they are residing, <mark>provided that they meet the duration of stay criteria for residence in the country</mark>."}, "IMTM 53": {"s": "IMTM 2025, para 53", "t": "… Also, persons can become citizens even though they have never lived in the country (e.g., children of citizens living abroad). <mark>Alternatively, persons may be born in the country but remain foreign citizens.</mark> … <mark>For instance, many refugees have been born in displacement and have never migrated during their lifetimes. In this case, they would be included in the native-born foreign-citizen resident population group unless they naturalized.</mark>"}, "IMTM 57": {"s": "IMTM 2025, para 57", "t": "… Births to foreign-born persons are automatically native-born and are added to the native-born population. <mark>The determination of foreign citizens born in the country, however, depends on the legislation in each country</mark> with some countries designating them citizens and others foreign citizens (i.e., jus sanguinis and jus soli systems)."}, "IMTM 58-61": {"s": "IMTM 2025, paras 58-61", "t": "… The R term represents persons not changing their resident population status, including <mark>those not transferring from being a foreign citizen (F) to a national citizen (C)</mark>, denoted by TF-C. For example, the demographic accounting model for the foreign citizen population is: PF(t+1) = PF(t) - EF - DF - TF-C + IF + BF. … [para 61] Note that births to foreign-born citizens are not included because they would be considered native born and added to the native-born foreign citizen or citizen population."}, "IMTM Fig. 2": {"s": "IMTM 2025, Figure 2 (summary)", "t": "Intersection between duration of stay and international mobility. International arrivals meeting the minimum residence requirement become new residents (immigrants); those below it are temporary (non-resident) mobility and join the temporary population, <mark>moving to new residents if the stay passes the minimum duration</mark>. <mark>Residents returning from a temporary stay abroad</mark> rejoin the resident population without being immigrants."}, "IMTM Fig. 3": {"s": "IMTM 2025, Figure 3 (summary)", "t": "International mobility covered by the Recommendations: international migration (change in residence) versus international temporary mobility (no change in residence), which includes labour-related stays, <mark>asylum seekers (including those in transit)</mark>, health-related stays and education-related stays."}, "IMTM Fig. 5": {"s": "IMTM 2025, Figure 5 (summary)", "t": "Examples of temporary population mobility by length of stay: days (commuting, asylum seekers or other persons in transit), weeks (training, seasonal workers, asylum seekers in transit) and months (training, seasonal or short-term workers, au pairs, <mark>forcibly displaced persons</mark>)."}, "IMTM Box 1": {"s": "IMTM 2025, Box 1", "t": "Special Statistical Considerations for Refugees and Asylum-Seekers. … Countries are strongly encouraged to implement the detailed guidance provided in the International Recommendations on Refugee Statistics (IRRS) … When relevant to the national policy context, <mark>countries may choose to include “reason for migration” or “legal status”</mark> …"}, "IMTM Table 1": {"s": "IMTM 2025, Table 1 (summary)", "t": "Core migration statistics on stocks and flows. Primary disaggregation: age, sex, country of birth, country of citizenship. Secondary topics include duration of stay, labour force status and <mark>reasons for migration</mark>."}, "IMTM Table 5": {"s": "IMTM 2025, Table 5 (summary)", "t": "Accounting table for the resident population by citizenship and birthplace, with <mark>births to native-born foreign citizens (B NB/F)</mark> and <mark>transfers from native-born foreign citizen to native-born citizen (T NB/F-NB/C)</mark> shown as separate components."}, "IRIS 86": {"s": "IRIS 2020, para 86", "t": "Returning refugees may have very similar characteristics to IDPs … however, they are not automatically counted as IDPs. These people fall within the scope of the IRRS … <mark>They are not counted as IDPs upon return, regardless of the period of time they were abroad</mark>, in order to avoid double counting in official statistics. … Following their return, <mark>if they are displaced again as a result of a new causing event they will become IDPs</mark>."}, "IRIS 98": {"s": "IRIS 2020, para 98", "t": "The emigration of a person who has displacement-related protection needs and vulnerabilities or an IDP-related person would also lead to a reduction in the stock of the respective population. <mark>Leaving the country of displacement should be aligned with the statistical definition of migration</mark> (see Box 3.2)."}, "IRIS 99": {"s": "IRIS 2020, para 99", "t": "This emigration can take place with the intention of seeking asylum in another country, with these persons <mark>forming part of the refugee stock if the reason for migrating was to escape from a ‘well-founded fear of persecution’</mark>. Alternatively, IDPs might emigrate to establish a place of usual residence in another country for other reasons … in which case they will be considered to have migrated."}, "IRIS 117": {"s": "IRIS 2020, para 117", "t": "In some circumstances the causing event may result in IDPs crossing an internationally recognised border in search of refuge … <mark>IDPs who cross an internationally recognised border but who subsequently return within a 12-month period without establishing a new usual residence abroad should continue to be considered as IDPs</mark> … Alternatively, IDPs who cross an internationally recognised border, return only after 12 months and/or have established a new country of usual residence should not be automatically considered to be IDPs."}};
Object.assign(PARAS,{"IRIS 83":{"s":"IRIS 2020, para 83","t":"<mark>Displaced persons who cross an internationally recognised border are subject to different frameworks depending on the cause of their displacement.</mark> Under the 1951 Convention … a refugee is someone … outside the country of his nationality … These people are within the scope of the IRRS, whether or not they have applied for or been granted asylum."},"IRIS 84":{"s":"IRIS 2020, para 84","t":"Displaced persons who cross an internationally recognised border for other reasons, such as natural or human-made disasters, are not covered by refugee conventions … Statistically, <mark>this group is captured as a migrant population in the taxonomy of international inflows and outflows</mark> of people in the Recommendations on Statistics of International Migration, albeit without differentiating between those who were forcibly displaced and those whose decision to leave … was voluntary."},"IRRS 104":{"s":"IRRS 2018, para 104","t":"The flow of a refugee and refugee related population is the number of persons entering or leaving the specific population within a specific period of time … Note, this concept is different from the one used for migration flow, as it takes the “population in scope” as the reference unit and not the country. … <mark>There can also be flow within the stock from asylum seeker to refugee.</mark>"},"IRIS 75": {"s": "IRIS 2020, para 75", "t": "…an IDP is defined as a person who was forced or obliged to leave his or her place of habitual residence … and who is found within the internationally recognised borders of the country … <mark>An IDP who went abroad following the displacement for a temporary period of less than 12 months and/or who did not establish a new country of usual residence remains an IDP.</mark> The total stock … is divided into three sub-stocks … <mark>despite their physical location, they may still be suffering from displacement-related needs and vulnerabilities</mark>."}, "IRIS 78": {"s": "IRIS 2020, para 78", "t": "<mark>Children of at least one internally displaced parent who were born after the displacement occurred should not be included in the overall count</mark>, as they did not experience the displacement themselves. However … they should be observed and counted as a separate but related statistical category: IDP-related populations."}, "IRIS 80": {"s": "IRIS 2020, para 80", "t": "<mark>Other family members of IDPs not directly affected by the causing event should not be included in the stock of IDPs.</mark> However … they are included as a category in the framework but are not a primary focus of these recommendations."}, "IRIS 81": {"s": "IRIS 2020, para 81", "t": "Displaced people remain of concern and within the stock of IDPs <mark>until they have definitively overcome key displacement-related vulnerabilities, unless a new country of residence is established or they die</mark>. … this assessment needs to be made for all three sub-stock categories of IDPs."}, "IRIS 88": {"s": "IRIS 2020, para 88", "t": "<mark>Persons displaced by a disaster who are temporarily abroad for less than 12 months and who do not establish a new usual country of residence should be included in the scope of the IDP statistics</mark>. However, those who move abroad and stay for longer than 12 months … may later return … <mark>they cannot be considered IDPs, on the grounds that they have changed their country of usual residence</mark>…"}, "IRIS 89": {"s": "IRIS 2020, para 89", "t": "As for refugees, other internationally displaced persons who return from abroad after more than 12 months <mark>can be counted as IDPs only if they suffer a new displacement after returning</mark> to their habitual country of residence."}, "IRIS 102": {"s": "IRIS 2020, para 102", "t": "<mark>Nationality is irrelevant for identifying IDPs. Persons included in IDP statistics can be nationals, stateless persons or foreigners</mark> as long as the place they fled from at the time of the displacement was their place of usual residence, and they continue to reside within the internationally recognised boundaries of the country."}, "IRIS 115": {"s": "IRIS 2020, para 115", "t": "Internal migration statistics usually pertain to people who have moved from one administrative area to another, but <mark>people can be forcibly displaced from their homes and property and subsequently find shelter in the same local area</mark>. … <mark>The geographical criterion of the concept of displacement therefore goes beyond that of internal migration</mark> to include those displaced and remaining in the same administrative area … The important distinguishing feature is that the move from the dwelling is caused by a forced displacement rather than a voluntary move."}, "IRIS 116": {"s": "IRIS 2020, para 116", "t": "An IDP is found within the internationally recognised state borders of the country in which the displacement took place … Statistically, this means that <mark>the country of usual residence of the IDP continues to be the country concerned</mark>."}, "IMTM 26": {"s": "IMTM 2025, para 26", "t": "The emigrant population (stock) includes all national citizens or persons who were born in the country and are residing in another country at a given point in time. <mark>Residents leaving the country to become part of another country’s resident population within a given year (flow) … are emigrants</mark>."}, "P&R 2.61": {"s": "P&R Rev. 4, para 2.61", "t": "It is recommended that countries <mark>apply a 12-month threshold when determining a person’s place of usual residence</mark> … the place at which the person has lived continuously for most of the 12 months before census reference day (that is, <mark>for at least six months and one day</mark> …) or intends to live for at least six months …"}, "P&R 5.46": {"s": "P&R Rev. 4, para 5.46", "t": "[Difficult-to-enumerate groups] Refugees, asylum seekers and internally displaced persons … should be enumerated in both the population present count, and <mark>in the usual resident count if they meet the established duration criteria</mark>."}, "P&R 5.54": {"s": "P&R Rev. 4, para 5.54", "t": "Problems may also arise with persons who have (a) been residing at the place where they are enumerated for some time, but <mark>do not consider themselves to be residents of that place because they intend to return to their previous residence</mark> at some future time … clearly stated time limits … <mark>must be based upon the 12-month limit</mark> …"}, "P&R 5.63": {"s": "P&R Rev. 4, para 5.63", "t": "… For the purposes of measuring internal migration, <mark>migrants are defined as those persons who usually are residing in a civil division of the country at the time of the census, but were previously resident outside that division. That is, movements within the civil division should not be regarded as being migratory.</mark>"}, "P&R 5.64": {"s": "P&R Rev. 4, para 5.64", "t": "<mark>The place of birth for those persons born within the country is the civil division in which the person was born</mark>; for those born in other countries, it is the country of birth. … usually refers to the geographic unit where the mother of the individual resided at the time of the person’s birth…"}, "P&R 5.71": {"s": "P&R Rev. 4, para 5.71", "t": "<mark>The duration of residence is the interval of time up to the date of the census, expressed in complete years, during which each person has lived in</mark> (a) the locality that is his or her usual residence at the time of the census; or (b) the major or smaller civil division in which that locality is situated."}, "P&R 5.72": {"s": "P&R Rev. 4, para 5.72", "t": "… the interest is in length of residence in the major or smaller civil division, or the locality, but not in the particular housing unit. <mark>The concept of duration of residence also relates to the most recent move to the current place of usual residence.</mark>"}, "P&R 5.74": {"s": "P&R Rev. 4, para 5.74", "t": "The place of previous usual residence is <mark>the major or smaller civil division, or the foreign country, in which the individual resided immediately prior to migrating into the civil division of present usual residence</mark>."}, "P&R 5.76": {"s": "P&R Rev. 4, para 5.76", "t": "<mark>The place of usual residence at a specified date in the past is the major or smaller division, or the foreign country, in which the individual resided at a specified date preceding the census.</mark> … In most cases, this has been deemed to be one year or five years preceding the census…"}, "P&R 5.77": {"s": "P&R Rev. 4, para 5.77", "t": "The former reference date provides information for statistics of both recent internal and international migration during a single year, <mark>while the latter may be more appropriate for collecting data for longer-term analysis of migration</mark>. … a one-year recall is likely to result in more accurate information than a five-year recall."}, "P&R 5.80": {"s": "P&R Rev. 4, para 5.80", "t": "However, no matter what previous date is used, <mark>provision must be made for the treatment of infants and young children who are resident at the time of the census but would not have been born at the earlier date</mark>. Tabulations of the data should indicate the nature of the treatment of this group."}, "P&R 5.81": {"s": "P&R Rev. 4, para 5.81", "t": "Some countries may also wish to collect information on <mark>the reason for change of residence of persons who have reported a change of usual residence</mark> in accordance with conditions set out in paragraphs 5.74-5.80. The information should refer only to the main reason for such a change of residence."}, "P&R 5.83": {"s": "P&R Rev. 4, para 5.83", "t": "There are no recommendations on the specific reasons, and countries should devise a classification in accordance with their own needs. However, examples of some common reasons for change of residence include: a) work or employment … b) education and training; c) marriage, family reunification or family formation; <mark>d) forced displacement (conflict, persecution, human rights abuses, natural disasters, etc.)</mark>; or e) other specified reason."}});
const PALIAS={"P&R 5.71-5.80":["P&R 5.71","P&R 5.76","P&R 5.80"],"IRRS 92.1-92.2":["IRRS 92.1","IRRS 92.2"],"IRRS 92.2-92.3":["IRRS 92.2","IRRS 92.3"],"IRRS 92.3.ii-iii":["IRRS 92.3"],"IRRS 96-97":["IRRS 96","IRRS 97"],"IRIS 98-99":["IRIS 98","IRIS 99"],"IMTM Table 1 (reason for migration)":["IMTM Table 1"]};
function refHTML(str){
  return str.split(" · ").map(seg=>{const m=seg.match(/^(IRRS|IMTM|IRIS|P&R)\s+(?:paras?\s+)?(.*)$/); if(!m) return seg;
    const src=m[1], pre=seg.slice(0,seg.length-m[2].length);
    const items=m[2].split(", ").map(it=>{const key=src+" "+it; const keys=PALIAS[key]||[key]; const ok=keys.every(k=>PARAS[k]);
      return ok?`<span class="pref" tabindex="0" data-k="${keys.join("|")}">${it}</span>`:it;});
    return pre+items.join(", ");}).join(" · ");
}
function prefTip(el){return el.dataset.k.split("|").map(k=>{const p=PARAS[k];return `<div class="ptip"><span class="tt">${p.s}</span><p>${p.t}</p></div>`;}).join("");}
document.addEventListener("mouseover",e=>{const t=e.target.closest&&e.target.closest(".pref"); if(t){showTip(prefTip(t),e);}});
document.addEventListener("mousemove",e=>{if(e.target.closest&&e.target.closest(".pref")) placeTip(e);});
document.addEventListener("mouseout",e=>{const t=e.target.closest&&e.target.closest(".pref"); if(t&&!t.contains(e.relatedTarget)) hideTip();});
document.addEventListener("focusin",e=>{const t=e.target.closest&&e.target.closest(".pref"); if(t){const r=t.getBoundingClientRect();showTip(prefTip(t),{clientX:r.left,clientY:r.bottom});}});
document.addEventListener("focusout",e=>{if(e.target.closest&&e.target.closest(".pref")) hideTip();});
const V = {
  prot:{label:"International migrant, move linked to protection", c:"prot"},
  other:{label:"International migrant, other reason recorded", c:"other"},
  ret:{label:"Returned migrant: in the flow, not the immigrant stock", c:"ret"},
  never:{label:"Not an international migrant: resident only", c:"never"},
  temp:{label:"Not yet a migrant: temporary population", c:"temp"}
};
