let sel=null;
let caseSel=null;
function select(id){caseSel=null;sel=(sel===id)?null:id;renderSel();renderCase();}
document.getElementById("clear").addEventListener("click",()=>{sel=null;caseSel=null;renderSel();renderCase();});
const nm=id=>{const n=node[id];return n.col==="k"?`${id} ${n.l}`:n.l;};
function renderSel(){
  const ls=caseSel?LINKS.filter(l=>l.rs.some(r=>r.case===caseSel)):sel?LINKS.filter(l=>l.k===sel||l.m===sel||l.c===sel):LINKS;
  const on=!!(sel||caseSel);
  LINKS.forEach(l=>{l.el.classList.toggle("dim",on&&!ls.includes(l));l.el.classList.toggle("hi",on&&ls.includes(l));});
  document.querySelectorAll(".sqG").forEach(g=>g.classList.toggle("dimq",on&&!ls.includes(LINKS[+g.dataset.li])));
  if(on) ls.forEach(l=>l.el.parentNode.insertBefore(l.el,l.el.parentNode.querySelector(".hit")));
  const touched=new Set(on?ls.flatMap(l=>[l.k,l.m,l.c]):[]);
  Object.values(node).forEach(n=>n.g&&n.g.classList.toggle("touch",touched.has(n.id)));
  document.querySelectorAll(".pillG").forEach(g=>{g.classList.toggle("faded",!!caseSel&&g.dataset.case!==caseSel);g.classList.toggle("on",g.dataset.case===caseSel);});
  Object.values(node).forEach(n=>n.g&&n.g.classList.toggle("sel",n.id===sel));
  document.getElementById("clear").hidden=!on;
  const cn0=caseSel?`case ${caseSel}`:sel?nm(sel):null;
  document.getElementById("selinfo").textContent=on?`Showing routes for ${cn0}`:"Click a numbered pill for its worked example, or a box to isolate its routes.";
  document.getElementById("tabletitle").textContent=on?`Routes for ${cn0}`:"All routes";
  let rs=ls.flatMap(l=>l.rs); if(caseSel) rs=rs.filter(r=>r.case===caseSel);
  const kn=id=>CATS.find(c=>c.id===id).l, cn=id=>CELLS.find(c=>c.id===id).l;
  rs.sort((a,b)=>CATS.findIndex(c=>c.id===a.k)-CATS.findIndex(c=>c.id===b.k));
  document.getElementById("rows").innerHTML=rs.map(r=>`<tr class="${r.lk==="r"?"rare":""}"><td><button class="cpill ${caseType(r.case)}" data-case="${r.case}">${r.case}</button></td><td><b>${r.k}</b> ${kn(r.k)}</td><td>${HOW[r.e]}</td><td><span class="badge b-${r.v}">${V[r.v].label}</span></td><td>${cn(r.c)}</td><td><span class="lk lk-${r.lk}">${LKL[r.lk]}</span><div class="rex">${r.ex}</div>${r.t}<div class="refs rref">${refHTML(r.ref)}</div></td></tr>`).join("");
  document.querySelectorAll("#rows .cpill").forEach(b=>b.addEventListener("click",()=>selectCase(b.dataset.case)));
}



