const scW=document.getElementById("scens");
S.forEach((s,i)=>{const b=document.createElement("button");b.className="scen";b.dataset.id=s.id;b.innerHTML=`<span class="n">${i+1}</span>${s.name}`;b.addEventListener("click",()=>drawScen(s.id));scW.appendChild(b);});
const T=document.getElementById("timeline");
function tx(m){return 140+m*34;}
const RY={X:85,Y:225};
function drawScen(id){
  const s=S.find(s=>s.id===id);
  document.querySelectorAll(".scen").forEach(b=>b.setAttribute("aria-pressed",b.dataset.id===id));
  document.getElementById("scentitle").textContent=s.name;
  let h="";
  h+=`<rect class="band-x" x="140" y="35" width="816" height="100" rx="6"/><rect class="band-y" x="140" y="175" width="816" height="100" rx="6"/>`;
  h+=`<text x="128" y="80" text-anchor="end" font-weight="700" font-size="13">Country X</text><text x="128" y="96" text-anchor="end" class="sm">origin · IRIS</text>`;
  h+=`<text x="128" y="220" text-anchor="end" font-weight="700" font-size="13">Country Y</text><text x="128" y="236" text-anchor="end" class="sm">neighbour · IRRS / IMTM</text>`;
  h+=`<line class="border-line" x1="140" x2="956" y1="155" y2="155"/><text x="950" y="150" text-anchor="end" class="mono">INTERNATIONALLY RECOGNISED BORDER</text>`;
  for(let m=0;m<=24;m+=3){h+=`<line class="axis" x1="${tx(m)}" x2="${tx(m)}" y1="35" y2="275"/><text x="${tx(m)}" y="292" text-anchor="middle" class="mono">${m}m</text>`;}
  const tw=tx(s.cross+12); h+=`<line class="tw" x1="${tw}" x2="${tw}" y1="30" y2="280"/><text x="${tw+5}" y="28" class="mono" style="fill:var(--v-other)">12 months after crossing</text>`;
  let pts=[]; s.segs.forEach(([r,a,b],i)=>{ if(i>0) pts.push([tx(a),RY[r]]); else pts.push([tx(a),RY[r]]); pts.push([tx(b),RY[r]]); });
  h+=`<polyline class="trace" points="${pts.map(p=>p.join(",")).join(" ")}"/>`;
  s.marks.forEach(([m,r,l],i)=>{const x=tx(m),y=RY[r]; const up=(i%2===0)?-14:24;
    h+=`<circle class="dot" cx="${x}" cy="${y}" r="6"/><text x="${x+4}" y="${y+up}" font-size="12" font-weight="600">${l}</text>`;});
  T.innerHTML=h;
  document.getElementById("status").innerHTML=["IRIS","IRRS","IMTM"].map(k=>`<tr><td><span class="srcb srcb-${k.toLowerCase()}">${k}</span></td><td>${s.st[k][0]}</td><td>${s.st[k][1]}</td></tr>`).join("");
  document.getElementById("scennote").innerHTML=`<div class="note${s.q?" q":""}">${s.q?"<b>Open question.</b> ":""}${s.note}</div>`;
}
