  h+=`<rect x="800" y="320" width="280" height="300" rx="10" class="misR"/><text x="815" y="346" class="mono">NOT SETTLED BY THE</text><text x="815" y="362" class="mono">RECOMMENDATIONS</text><text x="815" y="378" class="sm">IRIS, IRRS and IMTM all apply</text>`;
