// hover tooltips on routes and pills
const tip=document.createElement("div"); tip.className="tip"; tip.hidden=true; document.body.appendChild(tip);
const caseRow=(id,l)=>{const n=NEST.find(x=>x.id===id); if(!n) return ""; const T=TYPES[n.t];
  const path=l?`<span class="tr">${l.k} → ${(MIDLAB[l.m]||[l.m])[0]} → ${CELLS.find(c=>c.id===l.c).l}</span>`:`<span class="tr">IRRS ${n.cats}</span>`;
  if(!l) return `<div class="tiprow"><span class="tdot sm ${T.c}">${id}</span><div><b>${n.h}</b><span class="tt">${T.n} · ${FW(id).join(" + ")}</span><p>${n.ex}</p>${path}</div></div>`;
  const cat=CATS.find(c=>c.id===l.k);
  return l.rs.filter(r=>r.case===id).map(r=>`<div class="tiprow"><span class="tdot sm ${T.c}">${id}</span><div><b>${id==="E"?"Expected route":n.h}</b><span class="tt">${T.n} · ${l.k} ${cat?cat.l:""}</span><span class="lk lk-${r.lk}">${LKL[r.lk]}</span><p class="rex">${r.ex}</p><p class="thisroute">${r.t}</p>${path}<span class="tr">Cite: ${r.ref}</span></div></div>`).join("");};
function placeTip(e){const pad=14;let x=e.clientX+pad,y=e.clientY+pad;const r=tip.getBoundingClientRect();
  if(x+r.width>innerWidth-8)x=e.clientX-r.width-pad; if(y+r.height>innerHeight-8)y=e.clientY-r.height-pad;
  tip.style.left=Math.max(8,x)+"px"; tip.style.top=Math.max(8,y)+"px";}
function showTip(html,e){tip.innerHTML=html;tip.hidden=false;placeTip(e);}
function hideTip(){tip.hidden=true;}
LINKS.forEach(l=>{const t=l.el.querySelector("title"); if(t) t.remove();
  const hit=el("path",{d:l.el.getAttribute("d"),class:"hit"+(l.rare?" rare":"")},l.el.parentNode);
  const ids=[...new Set(l.rs.map(r=>r.case))];
  hit.addEventListener("mouseenter",e=>{showTip(ids.map(id=>caseRow(id,l)).join(""),e);l.el.classList.add("hov");
    l.el.parentNode.insertBefore(l.el,l.el.parentNode.querySelector(".hit")); svg.classList.add("hovering");
    const li=String(LINKS.indexOf(l)); document.querySelectorAll(".pillG,.sqG").forEach(g=>g.classList.toggle("hovp",g.dataset.li===li));
    [l.k,l.m,l.c].forEach(id=>node[id].g.classList.add("hovtouch","touch"));});
  hit.addEventListener("mousemove",placeTip);
  hit.addEventListener("mouseleave",()=>{hideTip();l.el.classList.remove("hov");svg.classList.remove("hovering");
    document.querySelectorAll(".pillG.hovp,.sqG.hovp").forEach(g=>g.classList.remove("hovp"));
    document.querySelectorAll(".node.hovtouch").forEach(g=>g.classList.remove("hovtouch","touch")); if(sel||caseSel) renderSel();});
  hit.addEventListener("click",()=>selectCase(ids[0]));
});
document.querySelectorAll(".pillG").forEach(g=>{const t=g.querySelector("title"); if(t) t.remove();
  g.addEventListener("mouseenter",e=>showTip(caseRow(g.dataset.case),e)); g.addEventListener("mousemove",placeTip); g.addEventListener("mouseleave",hideTip);
  g.addEventListener("focus",()=>{const r=g.getBoundingClientRect();showTip(caseRow(g.dataset.case),{clientX:r.right,clientY:r.bottom});}); g.addEventListener("blur",hideTip);});
renderSel(); renderCase();

